# CUDA kernel with shared memory, loop unrolling, and bank conflict avoidance
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles with padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; t += UNROLL_FACTOR) {
        // Prefetch multiple tiles
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int tile = t + i;
            if (tile < numTiles) {
                // Load tile from A
                int a_col = tile * TILE_SIZE + tx;
                if (row < N && a_col < N) {
                    As[ty][tx] = A[row * N + a_col];
                } else {
                    As[ty][tx] = 0.0f;
                }

                // Load tile from B
                int b_row = tile * TILE_SIZE + ty;
                if (b_row < N && col < N) {
                    Bs[ty][tx] = B[b_row * N + col];
                } else {
                    Bs[ty][tx] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial sums for prefetched tiles
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int tile = t + i;
            if (tile < numTiles) {
                for (int k = 0; k < TILE_SIZE; k++) {
                    sum += As[ty][k] * Bs[k][tx];
                }
            }
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

